public static class EntitlementFeatures{public const string UnlimitedEvents="unlimited.events",UnlimitedStorage="unlimited.storage",AIStudio="ai.studio",Gallery="gallery",Printing="printing",QrGallery="qr.gallery",CRM="crm",Marketing="marketing",Analytics="analytics",TemplateStudio="template.studio",ApiAccess="api.access",WhiteLabel="white.label",CustomDomain="custom.domain",LiveSlideshow="live.slideshow",VideoBooth="booth.video",GifBooth="booth.gif",Boomerang="booth.boomerang",DslrSupport="dslr.support",PrioritySupport="priority.support";public static readonly string[]All=[UnlimitedEvents,UnlimitedStorage,AIStudio,Gallery,Printing,QrGallery,CRM,Marketing,Analytics,TemplateStudio,ApiAccess,WhiteLabel,CustomDomain,LiveSlideshow,VideoBooth,GifBooth,Boomerang,DslrSupport,PrioritySupport];}
public sealed class EntitlementPlan:BaseEntity{private EntitlementPlan(){}public EntitlementPlan(Guid id,SubscriptionPlan code,string name,decimal monthly,decimal yearly,string description,int order){Id=id;Code=code;Update(name,monthly,yearly,description,order);IsActive=true;}public SubscriptionPlan Code{get;private set;}public string Name{get;private set;}=string.Empty;public decimal MonthlyPrice{get;private set;}public decimal YearlyPrice{get;private set;}public string Description{get;private set;}=string.Empty;public bool IsActive{get;private set;}public int DisplayOrder{get;private set;}public int MaximumEvents{get;private set;}public int MaximumTeamMembers{get;private set;}public long MaximumStorage{get;private set;}public int MaximumGalleries{get;private set;}public int MaximumAIJobs{get;private set;}public int MaximumTemplates{get;private set;}public int MaximumUploads{get;private set;}public int MaximumMonthlyCaptures{get;private set;}public int MaximumApiRequests{get;private set;}public ICollection<PlanFeature>Features{get;private set;}=[];public void Update(string name,decimal monthly,decimal yearly,string description,int order){Name=name.Trim();MonthlyPrice=monthly;YearlyPrice=yearly;Description=description.Trim();DisplayOrder=order;}public void SetLimits(int events,int members,long storage,int galleries,int ai,int templates,int uploads,int captures,int api){MaximumEvents=events;MaximumTeamMembers=members;MaximumStorage=storage;MaximumGalleries=galleries;MaximumAIJobs=ai;MaximumTemplates=templates;MaximumUploads=uploads;MaximumMonthlyCaptures=captures;MaximumApiRequests=api;}public void Archive()=>IsActive=false;}
public sealed class FeatureDefinition:BaseEntity{private FeatureDefinition(){}public FeatureDefinition(Guid id,string key,string name,string description){Id=id;Key=key;Name=name;Description=description;}public string Key{get;private set;}=string.Empty;public string Name{get;private set;}=string.Empty;public string Description{get;private set;}=string.Empty;}
public sealed class PlanFeature:BaseEntity{private PlanFeature(){}public PlanFeature(Guid planId,Guid featureId,bool enabled){PlanId=planId;FeatureId=featureId;Enabled=enabled;}public Guid PlanId{get;private set;}public EntitlementPlan Plan{get;private set;}=null!;public Guid FeatureId{get;private set;}public FeatureDefinition Feature{get;private set;}=null!;public bool Enabled{get;private set;}public void Set(bool enabled)=>Enabled=enabled;}
public sealed class OrganizationSubscription:BaseEntity{private OrganizationSubscription(){}public OrganizationSubscription(Guid organizationId,Guid planId,DateTime start,EntitlementSubscriptionStatus status=EntitlementSubscriptionStatus.Active){OrganizationId=organizationId;PlanId=planId;StartDate=start;Status=status;}public Guid OrganizationId{get;private set;}public Organization Organization{get;private set;}=null!;public Guid PlanId{get;private set;}public EntitlementPlan Plan{get;private set;}=null!;public EntitlementSubscriptionStatus Status{get;private set;}public DateTime StartDate{get;private set;}public DateTime?ExpiryDate{get;private set;}public DateTime?TrialEnd{get;private set;}public DateTime?RenewalDate{get;private set;}public void ChangePlan(Guid planId,DateTime?renewal=null){PlanId=planId;Status=EntitlementSubscriptionStatus.Active;RenewalDate=renewal;}public void StartTrial(Guid planId,int days){PlanId=planId;StartDate=DateTime.UtcNow;TrialEnd=DateTime.UtcNow.AddDays(days);Status=EntitlementSubscriptionStatus.Trial;}public void Evaluate(DateTime now){if(Status==EntitlementSubscriptionStatus.Trial&&TrialEnd<=now)Status=EntitlementSubscriptionStatus.Expired;else if(Status==EntitlementSubscriptionStatus.Active&&ExpiryDate<=now)Status=EntitlementSubscriptionStatus.Expired;}public void Suspend()=>Status=EntitlementSubscriptionStatus.Suspended;public void Cancel()=>Status=EntitlementSubscriptionStatus.Cancelled;}
public sealed class UsageRecord:BaseEntity{private UsageRecord(){}public UsageRecord(Guid organizationId,UsageMetric metric,long quantity,DateTime occurredAt,string?reference=null){OrganizationId=organizationId;Metric=metric;Quantity=quantity;OccurredAt=occurredAt;Reference=reference;}public Guid OrganizationId{get;private set;}public UsageMetric Metric{get;private set;}public long Quantity{get;private set;}public DateTime OccurredAt{get;private set;}public string?Reference{get;private set;}}
